ALTER TABLE `referral_signups` ADD `ipHash` varchar(255);
ALTER TABLE `referral_signups` ADD `isValid` boolean DEFAULT false NOT NULL;
ALTER TABLE `referral_signups` ADD `validatedAt` timestamp;
ALTER TABLE `referral_codes` DROP COLUMN `rewardClaimedAt`;

